package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)

	scanner.Scan()
	parts := strings.Split(scanner.Text(), " ")
	n, _ := strconv.Atoi(parts[0])
	k, _ := strconv.Atoi(parts[1])

	scanner.Scan()
	s := scanner.Text()

	freq := make(map[rune]int)
	for _, r := range s {
		freq[r]++
	}

	for _, count := range freq {
		if count > k {
			fmt.Print("NO")
			return
		}
	}

	fmt.Println("YES")
}

